    if (err?.code === "UNAUTHORIZED" || err?.status === -401 || err?.message?.includes("未授权") || err?.message?.includes("UNAUTHORIZED")) {
      const e2 = new Error("未授权访问 omp-service，请重新登录以获取完整授权");
      Object.assign(e2, { _oplusUnauth: true, _skillPath: AUTH_SKILL_PATH });
      throw e2;
    }
    throw err;
