async function cmdResult(args) {
  const taskId = args[0];
  if (!taskId || taskId.startsWith("-")) {
    writeStderr(`用法: oplus result <taskId>
`);
    process.exit(1);
  }
  const rawEnv = flag(args, "--env");
  const data = { taskId, limit: 100, event_types: ["agent.message", "session.status_idle"] };
  if (rawEnv !== undefined)
    data.env = rawEnv;
  const res = await oplusCall("getTaskEventList", data);
  if (res.code !== 0) {
    writeStderr(`❌ code=${res.code}: ${res.message}
`);
    process.exit(1);
  }
  const events = res.data?.events ?? [];
  let lastIdleId = null;
  for (let i = events.length - 1;i >= 0; i--) {
    if (events[i].type === "session.status_idle") {
      lastIdleId = events[i].id;
      break;
    }
  }
  if (!lastIdleId) {
    const detailData = { taskId };
    if (rawEnv !== undefined)
      detailData.env = rawEnv;
    const statusRes = await oplusCall("queryTaskDetail", detailData);
    const status = statusRes.data?.status ?? "unknown";
    print(`status: ${status}`);
    return;
  }
  let lastMsg = null;
  for (let i = events.length - 1;i >= 0; i--) {
    const ev = events[i];
    if (ev.type === "agent.message" && ev.id < lastIdleId) {
      lastMsg = ev;
      break;
    }
  }
  if (!lastMsg) {
    writeStderr(`任务已完成但无 agent 回复
`);
    process.exit(1);
  }
  if (hasFlag(args, "--json")) {
    print(lastMsg);
    return;
  }
  print(lastMsg.content?.map((c2) => c2.text ?? "").join("") ?? "");
}
